## Test 1: Successful receipt
```typescript
  test("receipt appears after successful submitAksRpE2eProjectComment", async () => {
    const browser = await puppeteer.launch({ executablePath: browserPath, headless: true, args: ["--no-sandbox", "--disable-setuid-sandbox"] });
    try {
      const page = await browser.newPage();
      await page.setRequestInterception(true);
      page.on("request", request => {
        const requestUrl = new URL(request.url());
        if (requestUrl.origin === server?.url.origin) request.continue();
        else request.abort();
      });
      if (!server) throw new Error("test server did not start");
      await page.goto(new URL("/#/feature/managedsystem-pool", server.url).toString(), { waitUntil: "domcontentloaded" });
      await page.waitForSelector(".aks-feature-page", { timeout: 10_000 });
      await page.evaluate(() => { (window as any).submitAksRpE2eProjectComment("audit feature managedsystem-pool (managedsystem-pool)"); });
      await page.waitForSelector('[data-testid="aks-receipt"]', { timeout: 10_000 });
      const receipt = await page.$eval('[data-testid="aks-receipt"]', el => el.textContent || "");
      expect(receipt).toContain("audit");
      expect(receipt).toContain("requested");
      expect(receipt).toContain("feature: managedsystem-pool");
      expect(receipt).toContain("owner: aks-explorer");
      expect(receipt).toMatch(/\d{4}-\d{2}-\d{2}/);
    } finally { await browser.close(); }
  }, 30_000);
```

## Test 2: Error receipt (HTTP 500)
```typescript
  test("error receipt appears after failed submitAksRpE2eProjectComment (HTTP 500)", async () => {
    const browser = await puppeteer.launch({ executablePath: browserPath, headless: true, args: ["--no-sandbox", "--disable-setuid-sandbox"] });
    try {
      const page = await browser.newPage();
      await page.setRequestInterception(true);
      page.on("request", request => {
        const requestUrl = new URL(request.url());
        if (requestUrl.pathname === "/api/projects/comment") {
          request.respond({ status: 500, contentType: "application/json", body: '{"error":"Internal Server Error"}' });
        } else if (requestUrl.origin === server?.url.origin) { request.continue(); }
        else { request.abort(); }
      });
      if (!server) throw new Error("test server did not start");
      await page.goto(new URL("/#/feature/managedsystem-pool", server.url).toString(), { waitUntil: "domcontentloaded" });
      await page.waitForSelector(".aks-feature-page", { timeout: 10_000 });
      await page.evaluate(() => { (window as any).submitAksRpE2eProjectComment("audit feature managedsystem-pool (managedsystem-pool)"); });
      await page.waitForSelector('[data-testid="aks-receipt"]', { timeout: 10_000 });
      const receipt = await page.$eval('[data-testid="aks-receipt"]', el => el.textContent || "");
      expect(receipt).toContain("error");
      expect(receipt).toContain("\u2717");
      expect(receipt).toContain("Recovery:");
      expect(receipt).toContain("owner: aks-explorer");
    } finally { await browser.close(); }
  }, 30_000);
```

